+      return NULL;
+    }
+    return p->second->lsnap;
+  }
+
+  // remove a snapshot from this database
+  const leveldb::Snapshot* removeSnapshot(int64_t id) {
+    const leveldb::Snapshot* l = lookupSnapshot(id);
+    if (l != NULL) {
