 class AtomicCounter {
  private:
   port::Mutex mu_;
   int count_;
  public:
   AtomicCounter() : count_(0) { }
   void Increment() {
     MutexLock l(&mu_);
     count_++;
   }
   int Read() {
     MutexLock l(&mu_);
     return count_;
   }
   void Reset() {
