+Status DBWithTTL::Put(
+    const WriteOptions& o,
+    const Slice& key,
+    const Slice& val) {
+  std::string value_with_ts;
+  Status st = AppendTS(val, value_with_ts);
+  if (!st.ok()) {
+    return st;
+  }
+  return db_->Put(o, key, value_with_ts);
+}
