  Status s = file->Read(handle.offset(), n + kBlockTrailerSize, &contents, buf);
  PERF_TIMER_MEASURE(block_read_time);
  PERF_COUNTER_ADD(block_read_count, 1);
  PERF_COUNTER_ADD(block_read_byte, n + kBlockTrailerSize);

