   for(int i = 0; i < num_buckets - 1; i++, time_point += bucket_size) {
     fprintf(stdout, "Keys in range %s to %s : %lu\n",
             ReadableTime(time_point).c_str(),
             ReadableTime(time_point + bucket_size).c_str(),
             (unsigned long)bucket_counts[i]);
