+std::string block_type_to_string(TraceType type) {
+  switch (type) {
+    case kBlockTraceFilterBlock:
+      return "Filter";
+    case kBlockTraceDataBlock:
+      return "Data";
+    case kBlockTraceIndexBlock:
+      return "Index";
+    case kBlockTraceRangeDeletionBlock:
+      return "RangeDeletion";
+    case kBlockTraceUncompressionDictBlock:
+      return "UncompressionDict";
+    default:
+      break;
+  }
+  // This cannot happen.
+  return "InvalidType";
+}
+
+std::string caller_to_string(BlockCacheLookupCaller caller) {
+  switch (caller) {
+    case kUserGet:
+      return "Get";
+    case kUserMGet:
+      return "MultiGet";
+    case kUserIterator:
+      return "Iterator";
+    case kPrefetch:
+      return "Prefetch";
+    case kCompaction:
+      return "Compaction";
+    default:
+      break;
+  }
+  // This cannot happen.
+  return "InvalidCaller";
+}
+}  // namespace
