+      if (for_compaction) {
+        s = Prefetch(file_reader_, offset, readahead_size_, for_compaction);
+      } else {
+        s = Prefetch(file_reader_, offset, n + readahead_size_, for_compaction);
+      }
       if (!s.ok()) {
         return false;
       }
       readahead_size_ = std::min(max_readahead_size_, readahead_size_ * 2);
     } else {
       return false;
