+ public:
+  // Gathers stats and saves results into `stats`
+  void GetStats(Stats *stats, int maximum_age_in_seconds = 180) {
+    // Waits for any pending reader or writer (collector)
+    std::lock_guard<std::mutex> lock(mutex_);
