+    // of the time and no more than once per second.
+    max_age_micros = std::min(
+        max_age_micros,
+        std::max(uint64_t{1000000},
+                 100U * (last_end_time_micros_ - last_start_time_micros_)));
+
+    uint64_t start_time_micros = clock_->NowMicros();
